@page "/settings"
@namespace sv_f3f776a45eac47a7a8c52415be647bfc.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

arguments.file_text:
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    display: flex;
    flex-direction: column;
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    flex-shrink: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    transition: background 0.15s, color 0.15s;
}

.sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

.sidebar-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #212529;
}

.settings-section h3 {
    margin: 1.25rem 0 0.75rem;
    font-size: 1.1rem;
    color: #333;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #495057;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
}

.btn-secondary:hover:not(:disabled) {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover:not(:disabled) {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
    animation: fadeIn 0.2s ease;
}

.toast-success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

.toast-error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Toggle Switch */
.toggle-group {
    margin-bottom: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-label input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #0d6efd;
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
    background: #f0f0f0;
}

.avatar-url-display {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Channels */
.channels-section {
    margin-top: 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 0.5rem;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    border: none;
    background: #f8f9fa;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* 2FA */
.twofa-section {
    margin-bottom: 1.5rem;
}

.twofa-status {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.status-indicator {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.status-on {
    background: #198754;
}

.status-off {
    background: #dc3545;
}

.info-text {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.5rem;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #495057;
}

.current-session-badge {
    font-size: 0.8rem;
    background: #d1e7dd;
    color: #0f5132;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
}

/* Dialog */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
}

.dialog h4 {
    margin: 0 0 0.75rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    flex-wrap: wrap;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

/* Appearance Preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

.preview-area h4 {
    margin: 0 0 0.75rem;
}

.preview-text {
    margin-bottom: 0.75rem;
}

.preview-card {
    background: #f8f9fa;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    border: 1px solid #e0e0e0;
}

/* Theme previews */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-card {
    background: #2d2d3d;
    border-color: #555;
    color: #e0e0e0;
}

.preview-system {
    background: #f5f5f5;
    color: #333;
}

/* Font size previews */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-area.compact {
    padding: 0.75rem;
